<?php declare(strict_types=1);require __DIR__.'/app/investment-participation.php';$user=require_verified();if(!investment_can_review($user)){http_response_code(403);exit('Platform administrator access required.');}$active='investment';$pageTitle='Investment funding control';$profiles=rows("SELECT p.*,u.email FROM investment_investor_profiles p JOIN users u ON u.id=p.user_id WHERE p.kyc_status='PENDING' ORDER BY p.updated_at");$contributions=rows("SELECT c.*,o.title,u.full_name FROM investment_capital_contributions c JOIN investment_opportunities o ON o.id=c.opportunity_id JOIN users u ON u.id=c.investor_user_id WHERE c.status='PENDING_CONFIRMATION' ORDER BY c.submitted_at");$opportunities=rows("SELECT o.*,(SELECT COALESCE(SUM(c.amount),0) FROM investment_capital_contributions c WHERE c.opportunity_id=o.id AND c.status='CONFIRMED') confirmed FROM investment_opportunities o WHERE o.status='PUBLISHED' AND o.publication_mode='INVESTABLE' ORDER BY o.updated_at DESC");require __DIR__.'/includes/operations-header.php';?>
<link rel="stylesheet" href="assets/css/investment-market.css?v=<?= filemtime(APP_ROOT.'/assets/css/investment-market.css') ?>"><article class="invest-portfolio"><h1>Funding control</h1><p>Human KYC, finance confirmation and procurement authorization controls.</p><h2>Pending investor verification</h2><table><tbody><?php foreach($profiles as $profile):?><tr><td><?= e($profile['legal_name']) ?><br><small><?= e($profile['email']) ?></small></td><td><?= e($profile['identity_reference']) ?> · <?= e($profile['tax_reference']) ?></td><td><form action="investment-participation-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="verify_profile"><input type="hidden" name="id" value="<?= e($profile['user_id']) ?>"><button name="kyc_status" value="VERIFIED">Verify</button><button name="kyc_status" value="REJECTED">Reject</button></form></td></tr><?php endforeach;?></tbody></table><h2>Unconfirmed capital</h2><table><tbody><?php foreach($contributions as $row):?><tr><td><?= e($row['full_name']) ?> · <?= e($row['title']) ?></td><td><?= e($row['currency']) ?> <?= number_format((float)$row['amount'],2) ?></td><td><form action="investment-participation-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="confirm"><input type="hidden" name="id" value="<?= e($row['id']) ?>"><input name="provider_reference" required placeholder="Bank/provider reference"><button>Confirm received</button></form></td></tr><?php endforeach;?></tbody></table><h2>Opportunity funding</h2><?php foreach($opportunities as $op):?><section><h3><?= e($op['title']) ?></h3><p><?= e(str_replace('_',' ',$op['funding_status'])) ?> · confirmed <?= e($op['currency']) ?> <?= number_format((float)$op['confirmed'],2) ?> of <?= number_format((float)$op['target_funding_amount'],2) ?></p><?php if($op['funding_status']==='NOT_OPEN'):?><form class="participation-form" action="investment-participation-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="funding_setup"><input type="hidden" name="id" value="<?= e($op['id']) ?>"><input type="number" name="minimum_participation" min="0.01" step="0.01" placeholder="Minimum participation" required><input type="datetime-local" name="funding_closes_at"><input name="finance_partner" value="<?= e($op['finance_security_partner']) ?>" placeholder="Finance partner" required><input name="bank_name" placeholder="Bank/provider" required><input name="account_name" placeholder="Controlled account name" required><input name="account_reference" placeholder="Controlled account reference" required><textarea name="instructions" placeholder="Authorized funding instructions" required></textarea><button>Open controlled funding</button></form><?php elseif($op['funding_status']==='TARGET_REACHED'):?><form action="investment-participation-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="authorize_procurement"><input type="hidden" name="id" value="<?= e($op['id']) ?>"><button>Authorize procurement</button></form><?php endif;?></section><?php endforeach;?></article><?php require __DIR__.'/includes/operations-footer.php';?>
